<script setup>
import {useForm,router} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PaginationLinks from '../../components/ui/PaginationLinks.vue';
const props=defineProps({date:String,routes:Array,collectedToday:[String,Number],paymentHistory:Object,upcomingVisits:Number,upcomingStops:Array,pendingStops:Array,lateCollections:Number,lateInstallments:Array,selectedRoute:Object,storeTemplate:String});
const money=v=>new Intl.NumberFormat('es-NI',{style:'currency',currency:'NIO'}).format(Number(v||0)); const forms=new Map();
const formFor=stop=>{if(!forms.has(stop.id))forms.set(stop.id,useForm({outcome:'collected',loan_id:stop.client.loans?.find(l=>['active','delinquent'].includes(l.status))?.id||'',amount:'',payment_method:'cash',reference:'',promise_date:'',notes:''}));return forms.get(stop.id)};
const submit=stop=>formFor(stop).post(props.storeTemplate.replace('__STOP__',stop.id),{preserveScroll:true});
</script>
<template><AppLayout title="Cobranza" eyebrow="Operación viva" description="Agenda, recaudo y seguimiento de compromisos."><template #header-actions><input type="date" :value="String(date).slice(0,10)" class="control m-0" @change="router.get('/cobranza',{date:$event.target.value})"></template><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><div class="live-metric" data-tone="emerald"><p>Cobrado en la fecha</p><strong>{{money(collectedToday)}}</strong></div><div class="live-metric" data-tone="blue"><p>Visitas pendientes</p><strong>{{pendingStops.length}}</strong></div><div class="live-metric" data-tone="gold"><p>Próximas visitas</p><strong>{{upcomingVisits}}</strong></div><div class="live-metric" data-tone="rose"><p>Cuotas vencidas</p><strong>{{lateCollections}}</strong></div></section><div class="mt-4 grid gap-4 xl:grid-cols-[1fr_360px]"><section class="card overflow-hidden"><div class="section-heading"><h2 class="font-semibold">Agenda de hoy</h2></div><div class="divide-y"><article v-for="stop in pendingStops" :key="stop.id" class="p-5"><div class="flex justify-between"><div><p class="font-semibold">{{stop.client.full_name}}</p><p class="text-[10px] text-slate-400">{{stop.route.name}} · {{stop.client.address}}</p></div><span class="badge bg-amber-50 text-amber-700">Pendiente</span></div><form class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="submit(stop)"><label class="field-label">Resultado<select v-model="formFor(stop).outcome" class="control"><option value="collected">Cobrado</option><option value="promise">Promesa</option><option value="no_payment">Sin pago</option><option value="not_found">No encontrado</option></select></label><template v-if="formFor(stop).outcome==='collected'"><label class="field-label">Crédito<select v-model="formFor(stop).loan_id" class="control"><option v-for="loan in stop.client.loans.filter(l=>['active','delinquent'].includes(l.status))" :key="loan.id" :value="loan.id">{{loan.number}}</option></select></label><label class="field-label">Monto<input v-model="formFor(stop).amount" type="number" min=".01" step=".01" class="control"></label><label class="field-label">Forma<select v-model="formFor(stop).payment_method" class="control"><option value="cash">Efectivo</option><option value="transfer">Transferencia</option><option value="deposit">Depósito</option></select></label></template><label v-if="formFor(stop).outcome==='promise'" class="field-label">Fecha prometida<input v-model="formFor(stop).promise_date" type="date" class="control"></label><label class="field-label sm:col-span-2">Notas<input v-model="formFor(stop).notes" class="control"></label><div class="flex items-end"><button class="btn-primary" :disabled="formFor(stop).processing">Registrar gestión</button></div></form><p v-if="Object.keys(formFor(stop).errors).length" class="mt-2 text-xs text-rose-600">{{Object.values(formFor(stop).errors).join(' · ')}}</p></article><p v-if="!pendingStops.length" class="empty-state">No hay visitas pendientes para esta fecha.</p></div></section><aside class="space-y-4"><section class="analytics-panel p-5 text-white"><p class="dark-kicker">Mora prioritaria</p><div class="mt-4 space-y-3"><div v-for="installment in lateInstallments.slice(0,6)" :key="installment.id" class="rounded-xl bg-white/5 p-3"><p class="text-xs font-semibold">{{installment.loan.client.full_name}}</p><p class="mt-1 text-[10px] text-slate-300">{{installment.loan.number}} · cuota {{installment.number}}</p></div><p v-if="!lateInstallments.length" class="text-xs text-slate-300">Sin cuotas vencidas.</p></div></section><section class="card overflow-hidden"><div class="section-heading"><h2 class="font-semibold">Historial reciente</h2></div><div class="divide-y"><div v-for="record in paymentHistory.data.slice(0,8)" :key="record.id" class="p-4"><div class="flex justify-between"><p class="text-xs font-semibold">{{record.client.full_name}}</p><p class="text-xs font-semibold text-emerald-700">{{record.amount?money(record.amount):record.outcome}}</p></div><p class="mt-1 text-[10px] text-slate-400">{{record.stop?.route?.name}}</p></div></div><PaginationLinks :links="paymentHistory.links"/></section></aside></div></AppLayout></template>
